// Some portions generated by Claude
package org.eclipse.rdf4j.sail.lmdb.evaluation;

import static org.assertj.core.api.Assertions.assertThat;

import java.io.File;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import java.util.TreeMap;
import java.util.stream.Collectors;

import org.eclipse.rdf4j.model.IRI;
import org.eclipse.rdf4j.model.Value;
import org.eclipse.rdf4j.model.ValueFactory;
import org.eclipse.rdf4j.model.vocabulary.RDF;
import org.eclipse.rdf4j.query.explanation.Explanation;
import org.eclipse.rdf4j.repository.sail.SailRepository;
import org.eclipse.rdf4j.sail.lmdb.LmdbStore;
import org.eclipse.rdf4j.sail.lmdb.config.LmdbStoreConfig;
import org.junit.jupiter.api.AfterEach;
import org.junit.jupiter.api.io.TempDir;
import org.junit.jupiter.api.parallel.ResourceLock;
import org.junit.jupiter.api.parallel.Resources;
import org.junit.jupiter.params.ParameterizedTest;
import org.junit.jupiter.params.provider.ValueSource;

/** A sibling VALUES table copied into a variable-selector graph keeps native and standard results identical. */
@ResourceLock(Resources.SYSTEM_PROPERTIES)
class LmdbGraphValuesCopyTest {

	private static final String NATIVE = "rdf4j.lmdb.nativeQueryEngine.enabled";
	private static final String EX = "http://example.com/";

	private static final String QUERY = "SELECT ?a ?g ?b ?c ?d ?e { "
			+ "VALUES ?a { <http://example.com/test1> <http://example.com/test2> <http://example.com/test3> } "
			+ "VALUES ?g { <http://example.com/g1> <http://example.com/g2> <http://example.com/g3> } "
			+ "GRAPH ?g { ?b a <http://example.com/Type1> . ?a a ?t . "
			+ "OPTIONAL { ?a <http://example.com/p1> ?c } OPTIONAL { ?b <http://example.com/p2> ?d } } "
			+ "OPTIONAL { GRAPH <http://example.com/meta> { ?g <http://example.com/p3> ?e } } }";

	private static final String BGP_QUERY = "SELECT ?a ?g ?t ?b ?d { "
			+ "VALUES ?a { <http://example.com/test1> <http://example.com/test2> } "
			+ "GRAPH ?g { ?a a ?t . ?b <http://example.com/p2> ?d } }";

	@TempDir
	File directory;
	private SailRepository repository;

	@AfterEach
	void tearDown() {
		if (repository != null) {
			repository.shutDown();
		}
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void siblingValuesCopyKeepsTheCompleteMultisetAndIsVisibleInTheOptimizedPlan(boolean experimental) {
		open(experimental);

		List<String> expected = rows(QUERY, false);
		assertThat(expected).isNotEmpty();
		// Hand-written oracle (neutral of both engines): g1 and g2 each have test1/test2, g3 only test1; ?e is
		// optional per graph (g2 has two); ?c only for test1 in g1 and g2.
		assertThat(expected).containsExactlyElementsOf(sorted(
				expectedRow("a", iri("test1"), "g", iri("g1"), "b", iri("b1"), "c", lit("c1"), "d", lit("d1"), "e",
						lit("e1")),
				expectedRow("a", iri("test2"), "g", iri("g1"), "b", iri("b1"), "d", lit("d1"), "e", lit("e1")),
				expectedRow("a", iri("test1"), "g", iri("g2"), "b", iri("b2"), "c", lit("c2"), "d", lit("d2"), "e",
						lit("e2a")),
				expectedRow("a", iri("test1"), "g", iri("g2"), "b", iri("b2"), "c", lit("c2"), "d", lit("d2"), "e",
						lit("e2b")),
				expectedRow("a", iri("test2"), "g", iri("g2"), "b", iri("b2"), "d", lit("d2"), "e", lit("e2a")),
				expectedRow("a", iri("test2"), "g", iri("g2"), "b", iri("b2"), "d", lit("d2"), "e", lit("e2b")),
				expectedRow("a", iri("test1"), "g", iri("g3"), "b", iri("b3"), "d", lit("d3"))));
		for (int invocation = 0; invocation < 2; invocation++) {
			assertThat(rows(QUERY, true)).as("native evaluation, run " + invocation)
					.containsExactlyElementsOf(expected);
			assertThat(rows(QUERY, false)).as("standard evaluation, run " + invocation)
					.containsExactlyElementsOf(expected);
		}
		String distinctQuery = QUERY.replace("SELECT ", "SELECT DISTINCT ");
		assertThat(rows(distinctQuery, true)).containsExactlyElementsOf(rows(distinctQuery, false));

		String plan = plan(QUERY);
		int graph = plan.indexOf("Graph [");
		int copy = plan.indexOf("BindingSetAssignment ([[a=http://example.com/test1]", graph);
		int typeLookup = plan.indexOf("o: Var (name=t)", graph);
		assertThat(graph).as(plan).isGreaterThanOrEqualTo(0);
		assertThat(copy).as("copied VALUES inside the graph body:%n%s", plan).isGreaterThan(graph);
		assertThat(copy).as("copied VALUES before the ?a lookup:%n%s", plan).isLessThan(typeLookup);
	}

	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void bgpOnlyBodyWithSiblingValuesIsFusedNatively(boolean experimental) {
		open(experimental);

		List<String> expected = sorted(
				expectedRow("a", iri("test1"), "g", iri("g1"), "t", iri("Class1"), "b", iri("b1"), "d", lit("d1")),
				expectedRow("a", iri("test2"), "g", iri("g1"), "t", iri("Class1"), "b", iri("b1"), "d", lit("d1")),
				expectedRow("a", iri("test1"), "g", iri("g2"), "t", iri("Class2"), "b", iri("b2"), "d", lit("d2")),
				expectedRow("a", iri("test2"), "g", iri("g2"), "t", iri("Class2"), "b", iri("b2"), "d", lit("d2")),
				expectedRow("a", iri("test1"), "g", iri("g3"), "t", iri("Class3"), "b", iri("b3"), "d", lit("d3")));

		assertThat(rows(BGP_QUERY, false)).as("standard evaluation").containsExactlyElementsOf(expected);
		assertThat(rows(BGP_QUERY, true)).as("native evaluation").containsExactlyElementsOf(expected);

		String telemetry = telemetry(BGP_QUERY);
		assertThat(telemetry).contains("c=?g#").contains("Values(rows=").doesNotContain("NativeGraph(selector=");
	}

	private IRI iri(String local) {
		return repository.getValueFactory().createIRI(EX + local);
	}

	private Value lit(String label) {
		return repository.getValueFactory().createLiteral(label);
	}

	private static String expectedRow(Object... nameValuePairs) {
		TreeMap<String, Value> sortedRow = new TreeMap<>();
		for (int i = 0; i < nameValuePairs.length; i += 2) {
			sortedRow.put((String) nameValuePairs[i], (Value) nameValuePairs[i + 1]);
		}
		return sortedRow.entrySet()
				.stream()
				.map(entry -> entry.getKey() + "=" + entry.getValue())
				.collect(Collectors.joining(";"));
	}

	private static List<String> sorted(String... rows) {
		return Arrays.stream(rows).sorted().toList();
	}

	private String telemetry(String query) {
		String previous = System.getProperty(NATIVE);
		System.setProperty(NATIVE, "true");
		try (var connection = repository.getConnection()) {
			return connection.prepareTupleQuery(query).explain(Explanation.Level.Telemetry).toString();
		} finally {
			restore(previous);
		}
	}

	private void open(boolean experimental) {
		LmdbStore store = new LmdbStore(directory, new LmdbStoreConfig("spoc,posc,ospc")
				.setNativeEvaluationEnabled(true)
				.setSketchEstimatorEnabled(false));
		store.setExperimentalQueryOptimizations(experimental);
		repository = new SailRepository(store);
		repository.init();
		ValueFactory vf = repository.getValueFactory();
		IRI type1 = vf.createIRI(EX + "Type1");
		try (var connection = repository.getConnection()) {
			for (int g = 1; g <= 3; g++) {
				IRI graph = vf.createIRI(EX + "g" + g);
				connection.add(vf.createIRI(EX + "b" + g), RDF.TYPE, type1, graph);
				connection.add(vf.createIRI(EX + "b" + g), vf.createIRI(EX + "p2"), vf.createLiteral("d" + g), graph);
				connection.add(vf.createIRI(EX + "test1"), RDF.TYPE, vf.createIRI(EX + "Class" + g), graph);
				if (g != 3) {
					connection.add(vf.createIRI(EX + "test2"), RDF.TYPE, vf.createIRI(EX + "Class" + g), graph);
					connection.add(vf.createIRI(EX + "test1"), vf.createIRI(EX + "p1"), vf.createLiteral("c" + g),
							graph);
				}
				for (int k = 0; k < 20; k++) {
					connection.add(vf.createIRI(EX + "x" + g + "_" + k), RDF.TYPE, vf.createIRI(EX + "Filler"), graph);
				}
			}
			IRI meta = vf.createIRI(EX + "meta");
			connection.add(vf.createIRI(EX + "g1"), vf.createIRI(EX + "p3"), vf.createLiteral("e1"), meta);
			connection.add(vf.createIRI(EX + "g2"), vf.createIRI(EX + "p3"), vf.createLiteral("e2a"), meta);
			connection.add(vf.createIRI(EX + "g2"), vf.createIRI(EX + "p3"), vf.createLiteral("e2b"), meta);
		}
	}

	private String plan(String query) {
		// The standard optimized plan is asserted here. With native evaluation on, explain prints the native physical
		// plan instead whenever the whole tree compiles natively, which the graph bind join ordering now allows.
		String previous = System.getProperty(NATIVE);
		System.setProperty(NATIVE, "false");
		try (var connection = repository.getConnection()) {
			return connection.prepareTupleQuery(query).explain(Explanation.Level.Optimized).toString();
		} finally {
			restore(previous);
		}
	}

	private List<String> rows(String query, boolean nativeEnabled) {
		String previous = System.getProperty(NATIVE);
		System.setProperty(NATIVE, Boolean.toString(nativeEnabled));
		try (var connection = repository.getConnection(); var result = connection.prepareTupleQuery(query).evaluate()) {
			List<String> rows = new ArrayList<>();
			while (result.hasNext()) {
				var row = result.next();
				rows.add(row.getBindingNames()
						.stream()
						.sorted()
						.map(name -> name + "=" + row.getValue(name))
						.collect(Collectors.joining(";")));
			}
			return rows.stream().sorted().toList();
		} finally {
			restore(previous);
		}
	}

	private static void restore(String previous) {
		if (previous == null) {
			System.clearProperty(NATIVE);
		} else {
			System.setProperty(NATIVE, previous);
		}
	}
}
